        .cfg_timeout_cycles(cfg_rd_timeout_cycles),
        .cfg_freq_sel(cfg_rd_freq_sel),
        .cfg_latency_threshold(cfg_rd_latency_threshold),
        .cfg_axi_pkt_mask(cfg_rd_axi_pkt_mask),
        .cfg_axi_err_select(cfg_rd_axi_err_select),
        .cfg_axi_error_mask(cfg_rd_axi_error_mask),
        .cfg_axi_timeout_mask(cfg_rd_axi_timeout_mask),
        .cfg_axi_compl_mask(cfg_rd_axi_compl_mask),
        .cfg_axi_thresh_mask(cfg_rd_axi_thresh_mask),
        .cfg_axi_perf_mask(cfg_rd_axi_perf_mask),
        .cfg_axi_addr_mask(cfg_rd_axi_addr_mask),
        .cfg_axi_debug_mask(cfg_rd_axi_debug_mask),

        // Monitor filter/CAM inputs (inert)
        .cam_clear(1'b0),
        .cfg_addr_filter_enable(1'b0),
        .cfg_addr_filter_low('0),
        .cfg_addr_filter_high('0),
        .cfg_id_filter_enable(1'b0),
        .cfg_id_match_base('0),
        .cfg_id_match_count('0),
        .debug_block_ready(),

        // Address-range checker (disabled at N_ADDR_RANGES=0)
        .cfg_addr_check_enable(1'b0),
        .cfg_addr_range_enable(1'b0),
        .cfg_addr_range_low({32{1'b0}}),
        .cfg_addr_range_high({32{1'b0}}),

        // Perfmon Stage A/B (tied off -- no window driven)
        .cfg_start_event_sel(3'b111),
        .cfg_end_event_sel(3'b111),
        .cfg_start_trigger(1'b0),
        .cfg_end_trigger(1'b0),
        .cfg_window_force_close(1'b0),
        .window_active(),
        .window_cycles(),
        .perf_prod_cycles(),
        .perf_bp_cycles(),
        .perf_starv_cycles(),
        .perf_idle_cycles(),
        .perf_beat_count(),
        .perf_byte_count(),
        .perf_burst_count()
    );

    logic [NUM_SLAVES-1:0] b_slave_select;
    logic [NUM_SLAVES-1:0] w_slave_select;
    logic [NUM_SLAVES-1:0] r_slave_select;
    // A5-3b: a read-return atomic (AWATOP[5]) answers on R, so its AW
    // also claims a slot in the AR->R tracking FIFO and must satisfy the
    // read side's single-outstanding-target gate. Declared here, driven
    // in the read-tracking section, consumed by aw_gate_ok.
    wire  aw_rr_atomic = fub_axi_awatop[5];
    logic aw_rr_gate_ok;
    // ... and one that decoded to the subtractive slave is answered locally
    // on R (DECERR); r_local_head marks its turn at the tracker head.
    logic r_local_head;

    // ================================================================
    // Address decode (slave selection) - Write
    // Slave 0 (ddr): 0x00000000 - 0x7FFFFFFF
    // Slave 1 (sram): 0x80000000 - 0xBFFFFFFF
    // Slave 2 (subtractive): 0x00000000 - 0xFFFFFFFF
    // ================================================================
    logic [NUM_SLAVES-1:0] comb_slave_select_aw;
    always_comb begin
        comb_slave_select_aw = '0;
        if (fub_axi_awaddr <= 32'h7FFFFFFF) begin
            comb_slave_select_aw[0] = 1'b1;  // ddr
        end
        else if (fub_axi_awaddr >= 32'h80000000 && fub_axi_awaddr <= 32'hBFFFFFFF) begin
            comb_slave_select_aw[1] = 1'b1;  // sram
        end
        else begin  // Full address range (catch-all)
            comb_slave_select_aw[2] = 1'b1;  // subtractive
        end
    end

    // Bridge ID for write channel (constant - tied to BRIDGE_ID parameter)
    assign bridge_id_aw = BRIDGE_ID_WIDTH'(BRIDGE_ID);

    // ================================================================
    // Address decode (slave selection) - Read
    // Slave 0 (ddr): 0x00000000 - 0x7FFFFFFF
    // Slave 1 (sram): 0x80000000 - 0xBFFFFFFF
    // Slave 2 (subtractive): 0x00000000 - 0xFFFFFFFF
    // ================================================================
    logic [NUM_SLAVES-1:0] comb_slave_select_ar;
    always_comb begin
        comb_slave_select_ar = '0;
        if (fub_axi_araddr <= 32'h7FFFFFFF) begin
            comb_slave_select_ar[0] = 1'b1;  // ddr
        end
        else if (fub_axi_araddr >= 32'h80000000 && fub_axi_araddr <= 32'hBFFFFFFF) begin
            comb_slave_select_ar[1] = 1'b1;  // sram
        end
        else begin  // Full address range (catch-all)
            comb_slave_select_ar[2] = 1'b1;  // subtractive
        end
    end

    // Bridge ID for read channel (constant - tied to BRIDGE_ID parameter)
    assign bridge_id_ar = BRIDGE_ID_WIDTH'(BRIDGE_ID);

    // ================================================================
    // Width adaptation - Master: 32b
    // Connected to slaves with widths: [32]
    // ================================================================

    // Per-width path-active gates (see comment in adapter_generator.py).
    logic aw_gate_ok;
    logic ar_gate_ok;
    logic aw_path_active_32b;
    assign aw_path_active_32b = (comb_slave_select_aw[0] | comb_slave_select_aw[1] | comb_slave_select_aw[2]) && aw_gate_ok;
    logic w_path_active_32b;
    assign w_path_active_32b = w_slave_select[0] | w_slave_select[1] | w_slave_select[2];
    logic ar_path_active_32b;
    assign ar_path_active_32b = (comb_slave_select_ar[0] | comb_slave_select_ar[1] | comb_slave_select_ar[2]) && ar_gate_ok;
    logic b_path_active_32b;
    assign b_path_active_32b = b_slave_select[0] | b_slave_select[1] | b_slave_select[2];
    logic r_path_active_32b;
    assign r_path_active_32b = (r_slave_select[0] | r_slave_select[1] | r_slave_select[2]) && !r_local_head;

    // ================================================================
    // Direct passthrough: 32b → 32b (no converter)
    // Requests: fub_axi_* → cpu_32b_*
    // Responses: cpu_32b_* → MUX → fub_axi_*
    // ================================================================

    // AW channel (request: fub → output)
    assign cpu_32b_aw.id     = fub_axi_awid;
    assign cpu_32b_aw.addr   = fub_axi_awaddr;
    assign cpu_32b_aw.len    = fub_axi_awlen;
    assign cpu_32b_aw.size   = fub_axi_awsize;
    assign cpu_32b_aw.burst  = fub_axi_awburst;
    assign cpu_32b_aw.lock   = fub_axi_awlock;
    assign cpu_32b_aw.cache  = fub_axi_awcache;
    assign cpu_32b_aw.prot   = fub_axi_awprot;
    assign cpu_32b_aw.qos    = fub_axi_awqos;
    assign cpu_32b_aw.region = 4'b0;  // AXI5 has no REGION
    assign cpu_32b_aw.user   = fub_axi_awuser;
    assign cpu_32b_aw.trace = fub_axi_awtrace;  // AXI5 sideband
    assign cpu_32b_aw.atop = fub_axi_awatop;  // AXI5 sideband
    assign cpu_32b_awvalid   = fub_axi_awvalid && aw_path_active_32b;
    // awready routed via MUX

    // W channel (request: fub → output)
    assign cpu_32b_w.data  = fub_axi_wdata;
    assign cpu_32b_w.strb  = fub_axi_wstrb;
    assign cpu_32b_w.last  = fub_axi_wlast;
    assign cpu_32b_w.user  = fub_axi_wuser;
    assign cpu_32b_wvalid  = fub_axi_wvalid && w_path_active_32b;
    // wready routed via MUX

    // B channel (response: output → MUX → fub)
    // Ready gated by the response head — see b_path_active comment.
    assign cpu_32b_bready = fub_axi_bready && b_path_active_32b;
    // bid, bresp, bvalid routed via MUX (user field ignored)

    // AR channel (request: fub → output)
    assign cpu_32b_ar.id     = fub_axi_arid;
    assign cpu_32b_ar.addr   = fub_axi_araddr;
    assign cpu_32b_ar.len    = fub_axi_arlen;
    assign cpu_32b_ar.size   = fub_axi_arsize;
    assign cpu_32b_ar.burst  = fub_axi_arburst;
    assign cpu_32b_ar.lock   = fub_axi_arlock;
    assign cpu_32b_ar.cache  = fub_axi_arcache;
    assign cpu_32b_ar.prot   = fub_axi_arprot;
    assign cpu_32b_ar.qos    = fub_axi_arqos;
    assign cpu_32b_ar.region = 4'b0;  // AXI5 has no REGION
    assign cpu_32b_ar.user   = fub_axi_aruser;
    assign cpu_32b_ar.trace = fub_axi_artrace;  // AXI5 sideband
    assign cpu_32b_arvalid   = fub_axi_arvalid && ar_path_active_32b;
    // arready routed via MUX

    // R channel (response: output → MUX → fub)
    // Ready gated by the response head — see r_path_active comment.
    assign cpu_32b_rready = fub_axi_rready && r_path_active_32b;
    // rid, rdata, rresp, rlast, rvalid routed via MUX (user field ignored)

    // ================================================================
    // Response MUX - Route responses from width-specific paths
    // back to fub_axi_* based on address decode
    //
    // Request side (arready/awready/wready) uses the combinational
    // slave_select_{ar,aw} (valid while {ar,aw}valid is asserted).
    //
    // Response side (rvalid/rdata/..., bvalid/bid/...) cannot reuse
    // the combinational decode because fub_axi_{ar,aw}addr no longer
    // holds the request address once the {AR,AW} handshake completes
    // -- the decode reverts (typically to slave 0) and drops the
    // response. So we track slave_select_{ar,aw} per outstanding
    // request in a small FIFO captured at handshake, popped at
    // R-last / B; the FIFO head drives the response MUX.
    // ================================================================

    // OUTPUT slave_select_aw mirrors the live combinational decode.
    assign slave_select_aw = comb_slave_select_aw;

    // -------- AW->B slave_select tracking FIFO --------
    localparam int AW_TRK_DEPTH = 16;
    localparam int AW_TRK_AW    = 4;
    logic [NUM_SLAVES-1:0] aw_trk_mem [AW_TRK_DEPTH];
    logic [AW_TRK_AW:0] aw_trk_wptr, aw_trk_rptr;
    logic aw_trk_push, aw_trk_pop;

    assign aw_trk_push = fub_axi_awvalid && fub_axi_awready;
    assign aw_trk_pop  = fub_axi_bvalid && fub_axi_bready;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            aw_trk_wptr <= '0;
            aw_trk_rptr <= '0;
        end else begin
            if (aw_trk_push) begin
                aw_trk_mem[aw_trk_wptr[AW_TRK_AW-1:0]] <= comb_slave_select_aw;
                aw_trk_wptr <= aw_trk_wptr + 1'b1;
            end
            if (aw_trk_pop) begin
                aw_trk_rptr <= aw_trk_rptr + 1'b1;
            end
        end
    )

    assign b_slave_select = (aw_trk_wptr != aw_trk_rptr)
                          ? aw_trk_mem[aw_trk_rptr[AW_TRK_AW-1:0]]
                          : '0;

    // -------- AW->B trace tracking (BRIDGE-012) --------
    // Same push/pop as the slave_select FIFO above, so the head is the
    // request being answered. Echoed onto btrace at the port below.
    logic aw_trk_trace [AW_TRK_DEPTH];
    logic b_trk_trace;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            for (int i = 0; i < AW_TRK_DEPTH; i++) aw_trk_trace[i] <= 1'b0;
        end else if (aw_trk_push) begin
            aw_trk_trace[aw_trk_wptr[AW_TRK_AW-1:0]] <= fub_axi_awtrace;
        end
    )

    assign b_trk_trace = (aw_trk_wptr != aw_trk_rptr)
                          ? aw_trk_trace[aw_trk_rptr[AW_TRK_AW-1:0]]
                          : 1'b0;

    // Single-outstanding-target (writes): only accept a new AW
    // while every outstanding write targets the SAME slave. The
    // B response mux replays responses in AW issue order; slaves
    // respond in their own accept order, so cross-slave outstanding
    // writes from several masters can deadlock the heads against
    // each other. Same-slave pipelining is unaffected.
    logic [NUM_SLAVES-1:0] r_aw_active_target;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            r_aw_active_target <= '0;
        end else if (aw_trk_push) begin
            r_aw_active_target <= comb_slave_select_aw;
        end
    )
    logic aw_trk_full;
    assign aw_trk_full = (aw_trk_wptr[AW_TRK_AW] != aw_trk_rptr[AW_TRK_AW]) &&
                         (aw_trk_wptr[AW_TRK_AW-1:0] == aw_trk_rptr[AW_TRK_AW-1:0]);
    assign aw_gate_ok = ((aw_trk_wptr == aw_trk_rptr) ||
                         (comb_slave_select_aw == r_aw_active_target)) &&
                        !aw_trk_full &&
                        // A5-3b: a read-return atomic also lives in the AR->R FIFO
                        (!aw_rr_atomic || aw_rr_gate_ok);

    // -------- AW->W slave_select tracking FIFO --------
    // Same push as AW (records slave_select at handshake);
    // pops on wlast so W#2's path-active gating doesn't wait
    // for B#1 to return. Without this, back-to-back writes
    // to different-width slaves stamp W#2's data on AW#1's
    // bucket (see multi-master 128b->32b/128b regression).
    logic [NUM_SLAVES-1:0] w_trk_mem [AW_TRK_DEPTH];
    logic [AW_TRK_AW:0] w_trk_wptr, w_trk_rptr;
    logic w_trk_push, w_trk_pop;

    assign w_trk_push = fub_axi_awvalid && fub_axi_awready;
    assign w_trk_pop  = fub_axi_wvalid && fub_axi_wready && fub_axi_wlast;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            w_trk_wptr <= '0;
            w_trk_rptr <= '0;
        end else begin
            if (w_trk_push) begin
                w_trk_mem[w_trk_wptr[AW_TRK_AW-1:0]] <= comb_slave_select_aw;
                w_trk_wptr <= w_trk_wptr + 1'b1;
            end
            if (w_trk_pop) begin
                w_trk_rptr <= w_trk_rptr + 1'b1;
            end
        end
    )

    assign w_slave_select = (w_trk_wptr != w_trk_rptr)
                          ? w_trk_mem[w_trk_rptr[AW_TRK_AW-1:0]]
                          : '0;

    // OUTPUT slave_select_ar mirrors the live combinational decode.
    assign slave_select_ar = comb_slave_select_ar;

    // -------- AR->R slave_select tracking FIFO --------
    localparam int AR_TRK_DEPTH = 16;
    localparam int AR_TRK_AW    = 4;
    logic [NUM_SLAVES-1:0] ar_trk_mem [AR_TRK_DEPTH];
    logic [AR_TRK_AW:0] ar_trk_wptr, ar_trk_rptr;
    logic ar_trk_push, ar_trk_pop;
    logic ar_trk_push_aw;
    // A5-3b: entries that must be answered locally (see r_local_head)
    logic ar_trk_local [AR_TRK_DEPTH];
    logic [3:0] ar_trk_id [AR_TRK_DEPTH];
    wire  aw_rr_local = aw_rr_atomic && comb_slave_select_aw[2];

    assign ar_trk_push = fub_axi_arvalid && fub_axi_arready;
    assign ar_trk_pop  = fub_axi_rvalid && fub_axi_rready && fub_axi_rlast;
    // A5-3b: a read-return atomic's AW claims an R-return slot too.
    assign ar_trk_push_aw = fub_axi_awvalid && fub_axi_awready && aw_rr_atomic;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            ar_trk_wptr <= '0;
            ar_trk_rptr <= '0;
        end else begin
            if (ar_trk_push && ar_trk_push_aw) begin
                ar_trk_mem[ar_trk_wptr[AR_TRK_AW-1:0]] <= comb_slave_select_ar;
                ar_trk_mem[AR_TRK_AW'(ar_trk_wptr[AR_TRK_AW-1:0] + 1'b1)] <= comb_slave_select_aw;
                ar_trk_local[ar_trk_wptr[AR_TRK_AW-1:0]] <= 1'b0;
                ar_trk_local[AR_TRK_AW'(ar_trk_wptr[AR_TRK_AW-1:0] + 1'b1)] <= aw_rr_local;
                ar_trk_id[AR_TRK_AW'(ar_trk_wptr[AR_TRK_AW-1:0] + 1'b1)] <= fub_axi_awid;
                ar_trk_wptr <= ar_trk_wptr + (AR_TRK_AW+1)'(2);
            end else if (ar_trk_push) begin
                ar_trk_mem[ar_trk_wptr[AR_TRK_AW-1:0]] <= comb_slave_select_ar;
                ar_trk_local[ar_trk_wptr[AR_TRK_AW-1:0]] <= 1'b0;
                ar_trk_wptr <= ar_trk_wptr + 1'b1;
            end else if (ar_trk_push_aw) begin
                ar_trk_mem[ar_trk_wptr[AR_TRK_AW-1:0]] <= comb_slave_select_aw;
                ar_trk_local[ar_trk_wptr[AR_TRK_AW-1:0]] <= aw_rr_local;
                ar_trk_id[ar_trk_wptr[AR_TRK_AW-1:0]] <= fub_axi_awid;
                ar_trk_wptr <= ar_trk_wptr + 1'b1;
            end
            if (ar_trk_pop) begin
                ar_trk_rptr <= ar_trk_rptr + 1'b1;
            end
        end
    )

    assign r_slave_select = (ar_trk_wptr != ar_trk_rptr)
                          ? ar_trk_mem[ar_trk_rptr[AR_TRK_AW-1:0]]
                          : '0;
    assign r_local_head = (ar_trk_wptr != ar_trk_rptr) &&
                          ar_trk_local[ar_trk_rptr[AR_TRK_AW-1:0]];

    // -------- AR->R trace tracking (BRIDGE-012) --------
    // Same push/pop as the slave_select FIFO above, so the head is the
    // request being answered. Echoed onto rtrace at the port below.
    logic ar_trk_trace [AR_TRK_DEPTH];
    logic r_trk_trace;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            for (int i = 0; i < AR_TRK_DEPTH; i++) ar_trk_trace[i] <= 1'b0;
        end else if (ar_trk_push && ar_trk_push_aw) begin
            ar_trk_trace[ar_trk_wptr[AR_TRK_AW-1:0]] <= fub_axi_artrace;
            ar_trk_trace[AR_TRK_AW'(ar_trk_wptr[AR_TRK_AW-1:0] + 1'b1)] <= fub_axi_awtrace;
        end else if (ar_trk_push_aw) begin
            ar_trk_trace[ar_trk_wptr[AR_TRK_AW-1:0]] <= fub_axi_awtrace;
        end else if (ar_trk_push) begin
            ar_trk_trace[ar_trk_wptr[AR_TRK_AW-1:0]] <= fub_axi_artrace;
        end
    )

    assign r_trk_trace = (ar_trk_wptr != ar_trk_rptr)
                          ? ar_trk_trace[ar_trk_rptr[AR_TRK_AW-1:0]]
                          : 1'b0;

    // Single-outstanding-target (reads) — see aw_gate_ok comment.
    logic [NUM_SLAVES-1:0] r_ar_active_target;
    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            r_ar_active_target <= '0;
        end else if (ar_trk_push_aw) begin
            r_ar_active_target <= comb_slave_select_aw;
        end else if (ar_trk_push) begin
            r_ar_active_target <= comb_slave_select_ar;
        end
    )
    logic ar_trk_full;
    assign ar_trk_full = (ar_trk_wptr[AR_TRK_AW] != ar_trk_rptr[AR_TRK_AW]) &&
                         (ar_trk_wptr[AR_TRK_AW-1:0] == ar_trk_rptr[AR_TRK_AW-1:0]);
    assign ar_gate_ok = ((ar_trk_wptr == ar_trk_rptr) ||
                         (comb_slave_select_ar == r_ar_active_target)) &&
                        !ar_trk_full;

    // A5-3b: the read-return atomic AW's own gate. Same target rule as
    // AR, but it needs TWO free slots so an AR handshaking in the same
    // cycle still fits (AR takes the first, the AW the second).
    //
    // The last term is load-bearing. With the FIFO empty, an AR and an
    // atomic AW to DIFFERENT slaves both pass their target rule in the same
    // cycle, and a dual push would then hold two targets at once. Every
    // slave whose tracker head belongs to this master drives the crossbar's
    // OR-merged response mux, so two live targets corrupt the R payload
    // (found as a seed-dependent read starvation in the A5-3b sign-off).
    // The AW yields in that cycle; it gets its turn once the FIFO drains.
    logic [AR_TRK_AW:0] ar_trk_count;
    assign ar_trk_count = ar_trk_wptr - ar_trk_rptr;
    assign aw_rr_gate_ok = ((ar_trk_wptr == ar_trk_rptr) ||
                            (comb_slave_select_aw == r_ar_active_target)) &&
                           (ar_trk_count <= (AR_TRK_AW+1)'(AR_TRK_DEPTH - 2)) &&
                           !(ar_trk_push && (comb_slave_select_ar != comb_slave_select_aw));

    // AW-ready MUX (combinational comb_slave_select_aw — awaddr is live during awvalid)
    always_comb begin
        fub_axi_awready = 1'b0;
        case (comb_slave_select_aw)
            3'b001: begin  // Slave 0 (32b)
                fub_axi_awready = cpu_32b_awready;
            end
            3'b010: begin  // Slave 1 (32b)
                fub_axi_awready = cpu_32b_awready;
            end
            3'b100: begin  // Slave 2 (32b)
                fub_axi_awready = cpu_32b_awready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Single-outstanding-target: hold off a new AW while writes
        // to a different slave are in flight (see aw_gate_ok).
        if (!aw_gate_ok) fub_axi_awready = 1'b0;
    end

    // W-ready MUX (FIFO-tracked w_slave_select — awaddr has already reverted by W phase)
    always_comb begin
        fub_axi_wready = 1'b0;
        case (w_slave_select)
            3'b001: begin  // Slave 0 (32b)
                fub_axi_wready = cpu_32b_wready;
            end
            3'b010: begin  // Slave 1 (32b)
                fub_axi_wready = cpu_32b_wready;
            end
            3'b100: begin  // Slave 2 (32b)
                fub_axi_wready = cpu_32b_wready;
            end
            default: begin
                // No active W transaction
            end
        endcase
    end

    // Write response MUX (B channel - uses b_slave_select FIFO head)
    // btrace is NOT driven here: the mux records what the SLAVE said
    // (checked below) while the port echoes the request (BRIDGE-012).
    logic b_slave_trace;
    always_comb begin
        fub_axi_bid = 4'd0;
        fub_axi_bresp = 2'b00;
        fub_axi_bvalid = 1'b0;
        b_slave_trace = '0;  // AXI5 sideband (trace)

        case (b_slave_select)
            3'b001: begin  // Slave 0 (32b)
                fub_axi_bid = cpu_32b_b.id[3:0];
                fub_axi_bresp = cpu_32b_b.resp;
                fub_axi_bvalid = cpu_32b_bvalid;
                b_slave_trace = cpu_32b_b.trace;
            end
            3'b010: begin  // Slave 1 (32b)
                fub_axi_bid = cpu_32b_b.id[3:0];
                fub_axi_bresp = cpu_32b_b.resp;
                fub_axi_bvalid = cpu_32b_bvalid;
                b_slave_trace = cpu_32b_b.trace;
            end
            3'b100: begin  // Slave 2 (32b)
                fub_axi_bid = cpu_32b_b.id[3:0];
                fub_axi_bresp = cpu_32b_b.resp;
                fub_axi_bvalid = cpu_32b_bvalid;
                b_slave_trace = cpu_32b_b.trace;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
    end


    // BRIDGE-012: the port promises trace; echo the request's bit.
    assign fub_axi_btrace = b_trk_trace;

`ifndef SYNTHESIS
    // A slave that DOES implement trace must echo it too. Echoing at the
    // boundary keeps this port correct whatever the slave does, but it
    // must not launder a trace-capable slave that returns the wrong bit.
    localparam logic [NUM_SLAVES-1:0] B_TRACE_CAPABLE = 3'b001;
    always_ff @(posedge aclk) begin
        if (aresetn && fub_axi_bvalid && fub_axi_bready &&
            |(b_slave_select & B_TRACE_CAPABLE) &&
            (b_slave_trace !== b_trk_trace)) begin
            $error("%m: BRIDGE-012: trace-capable slave returned btrace=%b for a request with trace=%b",
                   b_slave_trace, b_trk_trace);
        end
    end
`endif

    // AR-ready MUX (request side: uses combinational comb_slave_select_ar)
    always_comb begin
        fub_axi_arready = 1'b0;
        case (comb_slave_select_ar)
            3'b001: begin  // Slave 0 (32b)
                fub_axi_arready = cpu_32b_arready;
            end
            3'b010: begin  // Slave 1 (32b)
                fub_axi_arready = cpu_32b_arready;
            end
            3'b100: begin  // Slave 2 (32b)
                fub_axi_arready = cpu_32b_arready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Single-outstanding-target: hold off a new AR while reads
        // to a different slave are in flight (see ar_gate_ok).
        if (!ar_gate_ok) fub_axi_arready = 1'b0;
    end

    // Read response MUX (R channel - uses r_slave_select FIFO head)
    // rtrace is NOT driven here -- see the B-channel note (BRIDGE-012).
    logic r_slave_trace;
    always_comb begin
        fub_axi_rid = 4'd0;
        fub_axi_rdata = 32'd0;
        fub_axi_rresp = 2'b00;
        fub_axi_rlast = 1'b0;
        fub_axi_rvalid = 1'b0;
        r_slave_trace = '0;  // AXI5 sideband (trace)

        case (r_slave_select)
            3'b001: begin  // Slave 0 (32b)
                fub_axi_rid = cpu_32b_r.id[3:0];
                fub_axi_rdata = cpu_32b_r.data;
                fub_axi_rresp = cpu_32b_r.resp;
                fub_axi_rlast = cpu_32b_r.last;
                fub_axi_rvalid = cpu_32b_rvalid;
                r_slave_trace = cpu_32b_r.trace;
            end
            3'b010: begin  // Slave 1 (32b)
                fub_axi_rid = cpu_32b_r.id[3:0];
                fub_axi_rdata = cpu_32b_r.data;
                fub_axi_rresp = cpu_32b_r.resp;
                fub_axi_rlast = cpu_32b_r.last;
                fub_axi_rvalid = cpu_32b_rvalid;
                r_slave_trace = cpu_32b_r.trace;
            end
            3'b100: begin  // Slave 2 (32b)
                fub_axi_rid = cpu_32b_r.id[3:0];
                fub_axi_rdata = cpu_32b_r.data;
                fub_axi_rresp = cpu_32b_r.resp;
                fub_axi_rlast = cpu_32b_r.last;
                fub_axi_rvalid = cpu_32b_rvalid;
                r_slave_trace = cpu_32b_r.trace;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
        // A5-3b: a read-return atomic that decoded to the subtractive
        // slave is answered here -- DECERR, one beat, the AW's ID. The
        // subtractive slave has already been held off via r_path_active.
        if (r_local_head) begin
            fub_axi_rid    = ar_trk_id[ar_trk_rptr[AR_TRK_AW-1:0]];
            fub_axi_rdata  = 32'd0;
            fub_axi_rresp  = 2'b11;
            fub_axi_rlast  = 1'b1;
            fub_axi_rvalid = 1'b1;
        end
    end


    // BRIDGE-012: the port promises trace; echo the request's bit.
    assign fub_axi_rtrace = r_trk_trace;

`ifndef SYNTHESIS
    // A slave that DOES implement trace must echo it too. Echoing at the
    // boundary keeps this port correct whatever the slave does, but it
    // must not launder a trace-capable slave that returns the wrong bit.
    localparam logic [NUM_SLAVES-1:0] R_TRACE_CAPABLE = 3'b001;
    always_ff @(posedge aclk) begin
        if (aresetn && fub_axi_rvalid && fub_axi_rready &&
            |(r_slave_select & R_TRACE_CAPABLE) &&
            (r_slave_trace !== r_trk_trace)) begin
            $error("%m: BRIDGE-012: trace-capable slave returned rtrace=%b for a request with trace=%b",
                   r_slave_trace, r_trk_trace);
        end
    end
`endif

endmodule : cpu_adapter
